// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount < 1e30);
        uint256 before = c.pastBlockTime();
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 1);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        if (amount != 10 ether) {
            // Rule: any call whose value is not exactly 10 ether must revert
            // and leave pastBlockTime unchanged.
            assertFalse(ok);
            assertTrue(c.pastBlockTime() == before);
        } else {
            assertTrue(ok);
            assertTrue(c.pastBlockTime() > before);
        }
    }
}
